<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Authorship\AuthorshipResidentConstructionCommissionService;
use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name: 'imperium:mastermason:commission-chancellor', description: 'Issue the canonical Chancellor construction commission')]
final class MasterMasonCommissionChancellorCommand extends Command { public function __construct(private readonly AuthorshipResidentConstructionCommissionService $service) { parent::__construct(); } protected function configure(): void { $this->addArgument('provisioning-case-id', InputArgument::REQUIRED); } protected function execute(InputInterface $input, OutputInterface $output): int { try { $c = $this->service->issue('studium', (string) $input->getArgument('provisioning-case-id')); } catch (\Throwable $e) { $output->writeln('<error>REFUSED</error> '.$e->getMessage()); return self::FAILURE; } $output->writeln('<info>CHANCELLOR_CONSTRUCTION_COMMISSION_ISSUED</info> '.$c['commission_id']); $output->writeln('Target: '.$c['target_seat']); $output->writeln('Status: '.$c['status']); $output->writeln('Spawning authority: GRANTED FOR EXACT COMMISSION'); $output->writeln('Authorship authority: NOT GRANTED TO CONSCRIPTION'); $output->writeln('Subordinate Notary resolution: NOT GRANTED'); $output->writeln('Seat binding authority: NOT GRANTED'); $output->writeln('Recipient acceptance: NOT RECORDED'); $output->writeln('Execution authority: NOT GRANTED'); return self::SUCCESS; } }
